using MagasinGestion.Data;
using System.Data;

namespace MagasinGestion.Services;
public sealed record DashboardMetrics(decimal Sales, int SaleCount, decimal Units, int OutOfStock, int LowStock);
public sealed class ReportingService(SqliteConnectionFactory factory)
{
    public DashboardMetrics Dashboard(long? userId, DateTime day){using var db=factory.Create();var start=day.Date.ToUniversalTime().ToString("O");var end=day.Date.AddDays(1).ToUniversalTime().ToString("O");using var c=db.CreateCommand();c.CommandText="SELECT COALESCE(SUM(v.Total),0),COUNT(v.Id),COALESCE(SUM(l.Quantite),0) FROM Vente v LEFT JOIN LigneVente l ON l.VenteId=v.Id WHERE v.Annulee=0 AND v.DateVente >= $s AND v.DateVente < $e AND ($u IS NULL OR v.UtilisateurId=$u)";c.Parameters.AddWithValue("$s",start);c.Parameters.AddWithValue("$e",end);c.Parameters.AddWithValue("$u",(object?)userId??DBNull.Value);using var r=c.ExecuteReader();r.Read();var sales=r.GetDecimal(0);var count=r.GetInt32(1);var units=r.GetDecimal(2);r.Close();using var stock=db.CreateCommand();stock.CommandText="SELECT SUM(CASE WHEN Stock=0 THEN 1 ELSE 0 END),SUM(CASE WHEN Stock>0 AND Stock<=Seuil THEN 1 ELSE 0 END) FROM (SELECT p.StockMinimum Seuil,COALESCE(SUM(m.Quantite),0) Stock FROM Produit p LEFT JOIN MouvementStock m ON m.ProduitId=p.Id WHERE p.Actif=1 GROUP BY p.Id)";using var sr=stock.ExecuteReader();sr.Read();return new(sales,count,units,sr.IsDBNull(0)?0:sr.GetInt32(0),sr.IsDBNull(1)?0:sr.GetInt32(1));}
    public DataTable Daily(DateTime from,DateTime to){using var db=factory.Create();using var c=db.CreateCommand();c.CommandText="SELECT l.ReferenceEnregistree,l.NomEnregistre,SUM(l.Quantite),SUM(l.Total) FROM LigneVente l JOIN Vente v ON v.Id=l.VenteId WHERE v.Annulee=0 AND v.DateVente >= $s AND v.DateVente < $e GROUP BY l.ReferenceEnregistree,l.NomEnregistre ORDER BY l.NomEnregistre";c.Parameters.AddWithValue("$s",from.Date.ToUniversalTime().ToString("O"));c.Parameters.AddWithValue("$e",to.Date.AddDays(1).ToUniversalTime().ToString("O"));using var r=c.ExecuteReader();var table=new DataTable();table.Columns.Add("Reference");table.Columns.Add("Nom");table.Columns.Add("Unites",typeof(decimal));table.Columns.Add("Montant",typeof(decimal));while(r.Read())table.Rows.Add(r.GetString(0),r.GetString(1),r.GetDecimal(2),r.GetDecimal(3));return table;}
}
